window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-be0fb3bac9eafc74"]={"versions": [{"id": "FIG-be0fb3bac9eafc74", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Phasen- und Bereitstellungsmodell (Deployment & Lifecycle Workflow) mit systemischer Partitionierung in Off-board (Entwicklung, Integration, Packaging) und On-board (Zielsystem/Laufzeitumgebung <code>machine A</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R18-03 (EXP Platform Design, Kap. 3). Das Diagramm definiert die Trennung zwischen Design-Time-Modellierung, softwaretechnischer Aggregation zu Software-Packages und dem zielsystemseitigen Deployment-, Installations- und Prozess-Lifecycle über das Execution Management (EM) und Software Configuration Management (SWCM/UCM).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Off-board Entitäten (Entwicklung & Packaging)</p>\n<ul class=\"fig-list\">\n<li><strong>Entwicklungsprozesse & Aktivitäten:</strong></li>\n<li><code>Define Services</code>: Spezifikation serviceorientierter Schnittstellen unabhängig von Zielplattform und Sprache.</li>\n<li><code>Develop Platform and Configure Machine</code>: Spezifikation der Zielhardware, OS-Ressourcen und Netzwerktopologie.</li>\n<li><code>Develop Software</code>: Implementierung der <code>Adaptive Application</code> (Quellcode/C++-Artefakte gegen generierte Header aus den Service-Interfaces).</li>\n<li><code>Integrate Software</code>: Kompilierung und Bindung des Executables sowie Erstellung des Ausführungsmanifests.</li>\n<li><code>Define and Configure Service Instances</code>: Protokoll- und Kommunikationsbindung (z. B. SOME/IP, IPC, Signal-to-Service).</li>\n<li><strong>Artefakte & Manifeste (ARXML):</strong></li>\n<li><code>Service Interface Description</code>: Typdefinitionen, Methoden, Events, Fields (maschinenunabhängig).</li>\n<li><code>Machine Manifest</code>: Hardwareressourcen, Netzwerk-Endpunkte, CPU-Cores, OS- und Modus-Konfigurationen.</li>\n<li><code>Application Manifest</code>: Startup-Configs, Resource-Limits, Scheduling-Parameter, Execution-Dependencies.</li>\n<li><code>Service Instance Manifest</code>: Instanziierungsparameter, Service-IDs, Port-Mappings, Instanz-spezifische Kommunikationskonfiguration.</li>\n<li><code>SW Package</code>: Deployment-Container, der <code>executable</code> (ELF-Binary), <code>Application Manifest</code> und <code>Service Instance Manifest</code> bündelt.</li>\n</ul>\n<p class=\"fig-p\">#### On-board Entitäten (<code>machine A</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>SW Configuration Management (SWCM / UCM):</strong> On-board-Dienst zur Paketentgegennahme, Integritäts- und Authentizitätsprüfung, Entpackung und Registrierung.</li>\n<li><strong>installed executable 1:</strong> Im Ziel-Dateisystem abgelegtes Binärartefakt.</li>\n<li><strong>data base & processed manifests:</strong> Persistente Ablage für geparste, validierte Manifest-Informationen zur Laufzeitkonfiguration.</li>\n<li><strong>Execution Management (EM):</strong> Zentraler Lifecycle-Manager; konfiguriert das OS, steuert Prozessstarts/-stopps und überwacht Execution States.</li>\n<li><strong>OS (Operating System):</strong> POSIX-konformes Betriebssystem (Profile PSE51), zuständig für Speicherisolation, Multi-Threading und Scheduling.</li>\n<li><strong>process 1-1 (loaded executable instance):</strong> Konkrete Instanz des Binärprogramms im Adressraum des OS. Das Diagramm illustriert per kaskadiertem Kasten die Multi-Instanziierbarkeit desselben Executables in mehrere Prozesse.</li>\n<li><strong>Schnittstellen (APIs):</strong></li>\n<li>Standardisierte C++-APIs (<code>ara::*</code>) des Execution Management (z. B. Execution Client für State Reporting <code>kRunning</code>).</li>\n<li>POSIX-Systemschnittstellen (<code>API</code> an <code>OS</code>).</li>\n<li>Cluster-Schnittstellen (<code>API</code> an <code>other functional clusters</code>, z. B. <code>ara::com</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::diag</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Design & Schnittstellen-Definition (Off-board):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Services werden definiert (<code>Service Interface Description</code>); parallel wird die Zielmaschine deklariert (<code>Machine Manifest</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Implementierung, Kompilierung & Instanziierung (Off-board):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Anwendungsentwicklung erzeugt Quellcode gegen die Service Interfaces.</li>\n<li>Integration erzeugt das finale Binärprogramm (<code>executable</code>) und das zugehörige <code>Application Manifest</code>.</li>\n<li>Bindung an Kommunikations- und Netzwerkparameter erzeugt das <code>Service Instance Manifest</code>.</li>\n<li>Alle drei Komponenten werden in ein signiertes <code>SW Package</code> gebündelt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deployment, Verifikation & Installation (On-board):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>SW Package</code> wird off-board an das <code>SW Configuration Management</code> übertragen.</li>\n<li>SWCM validiert Signatur/Authentizität, dekomprimiert die Daten, installiert das Executable (<code>installed executable 1</code>) im Dateisystem und überführt die Manifeste in die systeminterne <code>data base</code> (<code>processed manifests</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prozess-Instanziierung & Lifecycle-Steuerung (Runtime):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> liest <code>processed manifests</code> aus der Datenbank aus (Konfiguration von Abhängigkeiten, Startup-Modi, OS-Rechten).</li>\n<li>EM instruiert das OS zur Prozess-Initialisierung (<code>fork</code>/<code>exec</code> bzw. POSIX-Äquivalent) und erzeugt <code>process 1-1</code>.</li>\n<li>Der gestartete Prozess meldet seinen Zustand synchron/asynchron über die EM-API zurück.</li>\n<li>Der Prozess kommuniziert über <code>ara::com</code> und greift auf weitere funktionale Cluster sowie POSIX-OS-Calls zu.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Trennung von Executable und Prozess (1:n-Mapping):</strong> Ein Binärartefakt (<code>executable</code>) ist zustandslos bezüglich seiner Laufzeitparameter. Erst die Verknüpfung aus <code>executable</code> und <code>Application Manifest</code> definiert die konkrete Prozessinstanz (<code>process 1-1</code>). Ein Executable kann über mehrere Manifeste mehrfach mit unterschiedlichen Berechtigungen, Budgets und Startparametern instanziiert werden.</li>\n<li><strong>Manifest-Trias & Konfigurationshoheit:</strong></li>\n<li>Code-Generatoren erzeugen bindingspezifische C++-Skelette/Proxies (<code>ara::com</code>) strikt aus der <code>Service Interface Description</code> und dem <code>Service Instance Manifest</code>.</li>\n<li>Das <code>Application Manifest</code> darf keine Kommunikationsendpunkte definieren; diese gehören normativ ins <code>Service Instance Manifest</code>.</li>\n<li><strong>Kein direkter OS-Launch:</strong> Applikationen dürfen im AP-Standard nicht direkt durch Init-Skripte oder Shells gestartet werden. Der Start erfolgt ausschließlich über das <code>Execution Management</code>, welches Mode-Management-Zustände (Machine State / Function Groups) und deterministische Startreihenfolgen erzwingt.</li>\n<li><strong>Sicherheits- & Integritätskette:</strong> Entwickler müssen sicherstellen, dass Software-Pakete den SWCM-Vorgaben für Metadaten und Signierung entsprechen. Unsignierte oder unvollständige Packages werden von SWCM vor dem Schreiben in Dateisystem und <code>data base</code> verworfen.</li>\n<li><strong>Schnittstellenrestriktion:</strong> Applikationen haben keinen direkten Hardware- oder Treiberzugriff; die Kommunikation muss ausnahmslos über die POSIX-PSE51-Teilmenge und funktionale <code>ara::*</code>-Cluster abgewickelt werden.</li>\n</ul>"}, {"id": "FIG-f1556c5b0d2477f3", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Phasen- und Bereitstellungsmodell (Deployment & Lifecycle Workflow) mit systemischer Partitionierung in Off-board (Entwicklung, Integration, Packaging) und On-board (Zielsystem/Laufzeitumgebung <code>machine A</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R18-03 (EXP Platform Design, Kap. 3). Das Diagramm definiert die Trennung zwischen Design-Time-Modellierung, softwaretechnischer Aggregation zu Software-Packages und dem zielsystemseitigen Deployment-, Installations- und Prozess-Lifecycle über das Execution Management (EM) und Software Configuration Management (SWCM/UCM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Off-board Entitäten (Entwicklung & Packaging)</p>\n<ul class=\"fig-list\">\n<li><strong>Entwicklungsprozesse & Aktivitäten:</strong></li>\n<li><code>Define Services</code>: Spezifikation serviceorientierter Schnittstellen unabhängig von Zielplattform und Sprache.</li>\n<li><code>Develop Platform and Configure Machine</code>: Spezifikation der Zielhardware, OS-Ressourcen und Netzwerktopologie.</li>\n<li><code>Develop Software</code>: Implementierung der <code>Adaptive Application</code> (Quellcode/C++-Artefakte gegen generierte Header aus den Service-Interfaces).</li>\n<li><code>Integrate Software</code>: Kompilierung und Bindung des Executables sowie Erstellung des Ausführungsmanifests (<code>Execution Manifest</code>).</li>\n<li><code>Define and Configure Service Instances</code>: Protokoll- und Kommunikationsbindung (z. B. SOME/IP, IPC, Signal-to-Service).</li>\n<li><strong>Artefakte & Manifeste (ARXML):</strong></li>\n<li><code>Service Interface Description</code>: Typdefinitionen, Methoden, Events, Fields (maschinenunabhängig).</li>\n<li><code>Machine Manifest</code>: Hardwareressourcen, Netzwerk-Endpunkte, CPU-Cores, OS- und Modus-Konfigurationen.</li>\n<li><code>Execution Manifest</code>: Startup-Configs, Resource-Limits, Scheduling-Parameter, Execution-Dependencies der konkreten ausführbaren Anwendung.</li>\n<li><code>Service Instance Manifest</code>: Instanziierungsparameter, Service-IDs, Port-Mappings, Instanz-spezifische Kommunikationskonfiguration.</li>\n<li><code>SW Package</code>: Deployment-Container, der <code>executable</code> (ELF-Binary), <code>Execution Manifest</code> und <code>Service Instance Manifest</code> bündelt.</li>\n</ul>\n<p class=\"fig-p\">#### On-board Entitäten (<code>machine A</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>SW Configuration Management (SWCM / UCM):</strong> On-board-Dienst zur Paketentgegennahme, Integritäts- und Authentizitätsprüfung, Entpackung und Registrierung.</li>\n<li><strong>installed executable 1:</strong> Im Ziel-Dateisystem abgelegtes Binärartefakt.</li>\n<li><strong>data base & processed manifests:</strong> Persistente Ablage für geparste, validierte Manifest-Informationen zur Laufzeitkonfiguration.</li>\n<li><strong>Execution Management (EM):</strong> Zentraler Lifecycle-Manager; konfiguriert das OS, steuert Prozessstarts/-stopps und überwacht Execution States.</li>\n<li><strong>OS (Operating System):</strong> POSIX-konformes Betriebssystem (Profile PSE51), zuständig für Speicherisolation, Multi-Threading und Scheduling.</li>\n<li><strong>process 1-1 (loaded executable instance):</strong> Konkrete Instanz des Binärprogramms im Adressraum des OS. Das Diagramm illustriert per kaskadiertem Kasten die Multi-Instanziierbarkeit desselben Executables in mehrere Prozesse.</li>\n<li><strong>Schnittstellen (APIs):</strong></li>\n<li>Standardisierte C++-APIs (<code>ara::*</code>) des Execution Management (z. B. Execution Client für State Reporting <code>kRunning</code>).</li>\n<li>POSIX-Systemschnittstellen (<code>API</code> an <code>OS</code>).</li>\n<li>Cluster-Schnittstellen (<code>API</code> an <code>other functional clusters</code>, z. B. <code>ara::com</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::diag</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Design & Schnittstellen-Definition (Off-board):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Services werden definiert (<code>Service Interface Description</code>); parallel wird die Zielmaschine deklariert (<code>Machine Manifest</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software-Implementierung & Integration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus den Service Interfaces entsteht die <code>Adaptive Application</code> (<code>Develop Software</code>).</li>\n<li><code>Integrate Software</code> kompiliert die Anwendung zum binären <code>executable</code> und erzeugt das <code>Execution Manifest</code>.</li>\n<li><code>Define and Configure Service Instances</code> verbindet Service Interfaces und Machine Manifest zu <code>Service Instance Manifest</code>-Artefakten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Packaging:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>executable</code>, <code>Execution Manifest</code> und <code>Service Instance Manifest</code> werden in ein <code>SW Package</code> gebündelt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deployment & On-board Installation (<code>machine A</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>SW Package</code> wird an das <code>SW Configuration Management</code> übergeben.</li>\n<li><code>SW Configuration Management</code> verifiziert und installiert das Binärartefakt als <code>installed executable 1</code> im Dateisystem.</li>\n<li>Die Manifeste werden geparst und als <code>processed manifests</code> in der persistenten <code>data base</code> hinterlegt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitsteuerung & Instanziierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> liest die Konfiguration aus <code>data base</code> / <code>processed manifests</code>, konfiguriert das <code>OS</code> und startet/stoppt Prozesse (<code>process 1-1</code>).</li>\n<li><code>process 1-1</code> interagiert über standardisierte <code>API</code>-Schnittstellen mit dem <code>Execution Management</code>, dem <code>OS</code> sowie <code>other functional clusters</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell- & Manifest-Struktur:</strong> Trennung von Maschinendefinition (<code>Machine Manifest</code>), Software-Design (<code>Service Interface Description</code>), Ausführungskonfiguration (<code>Execution Manifest</code>) und Bindung (<code>Service Instance Manifest</code>).</li>\n<li><strong>Multi-Instanziierung:</strong> Ein einzelnes <code>installed executable</code> kann mehrfach als getrennter Prozess (<code>process 1-1</code>, kaskadierte Boxen) mit unterschiedlichen Parametern/Rechten instantiiert werden.</li>\n<li><strong>Sicherheits- & Architektur-Isolation:</strong> Applikationsprozesse greifen ausschließlich über standardisierte funktionale Cluster-APIs (<code>ara::*</code>) und POSIX-Subset-Schnittstellen auf Plattformressourcen zu; direkte Zugriffe auf Manifeste oder andere Prozesse sind unterbunden.</li>\n<li><strong>Deployment-Autonomie:</strong> Durch das standardisierte <code>SW Package</code> erfolgt die Softwareverteilung und das Update entkoppelt von der initialen Plattformerstellung.</li>\n</ul>"}, {"id": "FIG-8926daf4e9bb6384", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Phasen- und Bereitstellungsmodell (Deployment & Lifecycle Workflow) mit systemischer Partitionierung in Off-board (Entwicklung, Integration, Packaging) und On-board (Zielsystem/Laufzeitumgebung <code>machine A</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R18-03 (EXP Platform Design, Kap. 3). Das Diagramm definiert die Trennung zwischen Design-Time-Modellierung, softwaretechnischer Aggregation zu Software-Packages und dem zielsystemseitigen Deployment-, Installations- und Prozess-Lifecycle über das Execution Management (EM) und Software Configuration Management (SWCM/UCM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Off-board Entitäten (Entwicklung & Packaging)</p>\n<ul class=\"fig-list\">\n<li><strong>Entwicklungsprozesse & Aktivitäten:</strong></li>\n<li><code>Define Services</code>: Spezifikation serviceorientierter Schnittstellen unabhängig von Zielplattform und Sprache.</li>\n<li><code>Develop Platform and Configure Machine</code>: Spezifikation der Zielhardware, OS-Ressourcen und Netzwerktopologie.</li>\n<li><code>Develop Software</code>: Implementierung der <code>Adaptive Application</code> (Quellcode/C++-Artefakte gegen generierte Header aus den Service-Interfaces).</li>\n<li><code>Integrate Software</code>: Kompilierung und Bindung des Executables sowie Erstellung des Ausführungsmanifests (<code>Execution Manifest</code>).</li>\n<li><code>Define and Configure Service Instances</code>: Protokoll- und Kommunikationsbindung (z. B. SOME/IP, IPC, Signal-to-Service).</li>\n<li><strong>Artefakte & Manifeste (ARXML):</strong></li>\n<li><code>Service Interface Description</code>: Typdefinitionen, Methoden, Events, Fields (maschinenunabhängig).</li>\n<li><code>Machine Manifest</code>: Hardwareressourcen, Netzwerk-Endpunkte, CPU-Cores, OS- und Modus-Konfigurationen.</li>\n<li><code>Execution Manifest</code>: Startup-Configs, Resource-Limits, Scheduling-Parameter, Execution-Dependencies der konkreten ausführbaren Anwendung.</li>\n<li><code>Service Instance Manifest</code>: Instanziierungsparameter, Service-IDs, Port-Mappings, Instanz-spezifische Kommunikationskonfiguration.</li>\n<li><code>SW Package</code>: Deployment-Container, der <code>executable</code> (ELF-Binary), <code>Execution Manifest</code> und <code>Service Instance Manifest</code> bündelt.</li>\n</ul>\n<p class=\"fig-p\">#### On-board Entitäten (<code>machine A</code>)</p>\n<ul class=\"fig-list\">\n<li><strong>SW Configuration Management (SWCM / UCM):</strong> On-board-Dienst zur Paketentgegennahme, Integritäts- und Authentizitätsprüfung, Entpackung und Registrierung.</li>\n<li><strong>installed executable 1:</strong> Im Ziel-Dateisystem abgelegtes Binärartefakt.</li>\n<li><strong>data base & processed manifests:</strong> Persistente Ablage für geparste, validierte Manifest-Informationen zur Laufzeitkonfiguration.</li>\n<li><strong>Execution Management (EM):</strong> Zentraler Lifecycle-Manager; konfiguriert das OS, steuert Prozessstarts/-stopps und überwacht Execution States.</li>\n<li><strong>OS (Operating System):</strong> POSIX-konformes Betriebssystem (Profile PSE51), zuständig für Speicherisolation, Multi-Threading und Scheduling.</li>\n<li><strong>process 1-1 (loaded executable instance):</strong> Konkrete Instanz des Binärprogramms im Adressraum des OS. Das Diagramm illustriert per kaskadiertem Kasten die Multi-Instanziierbarkeit desselben Executables in mehrere Prozesse.</li>\n<li><strong>Schnittstellen (APIs):</strong></li>\n<li>Standardisierte C++-APIs (<code>ara::*</code>) des Execution Management (z. B. Execution Client für State Reporting <code>kRunning</code>).</li>\n<li>POSIX-Systemschnittstellen (<code>API</code> an <code>OS</code>).</li>\n<li>Cluster-Schnittstellen (<code>API</code> an <code>other functional clusters</code>, z. B. <code>ara::com</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::diag</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Design & Schnittstellen-Definition (Off-board):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Services werden definiert (<code>Service Interface Description</code>); parallel wird die Zielmaschine deklariert (<code>Machine Manifest</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software-Implementierung & Integration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus den Service Interfaces entsteht die <code>Adaptive Application</code> (<code>Develop Software</code>).</li>\n<li><code>Integrate Software</code> kompiliert die Anwendung zum binären <code>executable</code> und erzeugt das <code>Execution Manifest</code>.</li>\n<li><code>Define and Configure Service Instances</code> verbindet Service Interfaces und Machine Manifest zu <code>Service Instance Manifest</code>-Artefakten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Packaging:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>executable</code>, <code>Execution Manifest</code> und <code>Service Instance Manifest</code> werden in ein <code>SW Package</code> gebündelt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deployment & On-board Installation (<code>machine A</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das <code>SW Package</code> wird an das <code>SW Configuration Management</code> übergeben.</li>\n<li><code>SW Configuration Management</code> verifiziert und installiert das Binärartefakt als <code>installed executable 1</code> im Dateisystem.</li>\n<li>Die Manifeste werden geparst und als <code>processed manifests</code> in der persistenten <code>data base</code> hinterlegt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitsteuerung & Instanziierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> liest die Konfiguration aus <code>data base</code> / <code>processed manifests</code>, konfiguriert das <code>OS</code> und startet/stoppt Prozesse (<code>process 1-1</code>).</li>\n<li><code>process 1-1</code> interagiert über standardisierte <code>API</code>-Schnittstellen mit dem <code>Execution Management</code>, dem <code>OS</code> sowie <code>other functional clusters</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell- & Manifest-Struktur:</strong> Trennung von Maschinendefinition (<code>Machine Manifest</code>), Software-Design (<code>Service Interface Description</code>), Ausführungskonfiguration (<code>Execution Manifest</code>) und Bindung (<code>Service Instance Manifest</code>).</li>\n<li><strong>Multi-Instanziierung:</strong> Ein einzelnes <code>installed executable</code> kann mehrfach als getrennter Prozess (<code>process 1-1</code>, kaskadierte Boxen) mit unterschiedlichen Parametern/Rechten instantiiert werden.</li>\n<li><strong>Sicherheits- & Architektur-Isolation:</strong> Applikationsprozesse greifen ausschließlich über standardisierte funktionale Cluster-APIs (<code>ara::*</code>) und POSIX-Subset-Schnittstellen auf Plattformressourcen zu; direkte Zugriffe auf Manifeste oder andere Prozesse sind unterbunden.</li>\n<li><strong>Deployment-Autonomie:</strong> Durch das standardisierte <code>SW Package</code> erfolgt die Softwareverteilung und das Update entkoppelt von der initialen Plattformerstellung.</li>\n</ul>"}], "trans": [{"from": "FIG-be0fb3bac9eafc74", "to": "FIG-f1556c5b0d2477f3", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Off-board Artefakte / Manifeste:</strong> Die Beschriftung des Manifest-Artefakts im <code>SW Package</code> wurde von <code>Application Manifest</code> in <code>Execution Manifest</code> umbenannt.</li>\n</ul>"}, {"from": "FIG-f1556c5b0d2477f3", "to": "FIG-8926daf4e9bb6384", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
